                              transform: isMovable ? 'scale(1.15)' : 'scale(1)',
                              animation: isMovable ? 'bounce 0.8s infinite alternate' : 'none',
                              zIndex: 10,
                              outline: 'none',
                              transition: 'all 0.2s',
                              WebkitTapHighlightColor: 'transparent',
                            }}
                          >
                            {baseToken.tokenId + 1}
                          </div>
                        )}
                      </div>
                    )
                  })}
                </div>
              </div>
            )
          })}

          {/* Center Goal */}
          <div
            style={{
              gridRow: '7/10',
              gridColumn: '7/10',
              background: 'conic-gradient(from -45deg, #eab308 0deg 90deg, #2563eb 90deg 180deg, #dc2626 180deg 270deg, #16a34a 270deg 360deg)',
              border: '1px solid #cbd5e1',
              boxSizing: 'border-box',
              position: 'relative',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
            }}
          >
            {tokens.filter(t => t.posType === 'done').map((token, idx) => {
              const cfg = activePlayers.find(p => p.id === token.playerId)!
              return (
                <div
                  key={`done-${token.playerId}-${token.tokenId}`}
                  style={{
                    position: 'absolute',
                    width: 14,
                    height: 14,
                    borderRadius: '50%',
                    background: cfg.color,
                    border: '1px solid #fff',
                    boxShadow: '0 0 4px rgba(0,0,0,0.5)',
                    transform: `translate(${(idx % 2) * 14 - 7}px, ${Math.floor(idx / 2) * 14 - 7}px)`,
                    zIndex: 15,
                  }}
                />
              )
            })}
          </div>

          {/* Render 72 Arm Squares */}
          {ARM_CELLS.map(({ r, c }) => {
            const theme = getCellTheme(r, c)
            const cellTokens = getTokensAt(r, c)

            return (
              <div
                key={`cell-${r}-${c}`}
                style={{
                  gridRow: r + 1,
                  gridColumn: c + 1,
                  background: theme.background,
                  border: '1px solid #cbd5e1',
                  display: 'flex',
                  flexWrap: 'wrap',
                  alignItems: 'center',
                  justifyContent: 'center',
                  position: 'relative',
                  boxSizing: 'border-box',
                }}
              >
                {theme.isSafe && (
                  <div style={{
                    position: 'absolute',
                    color: '#ffd700',
                    fontSize: 14,
                    fontWeight: 'bold',
                    opacity: cellTokens.length > 0 ? 0.25 : 0.85,
                    textShadow: '0 0 2px rgba(0,0,0,0.5)',
                    zIndex: 1,
                  }}>★</div>
                )}

                {theme.arrow && (
                  <div style={{
                    position: 'absolute',
                    color: theme.arrowColor || '#ffffff',
                    fontSize: 14,
                    fontWeight: 'bold',
                    opacity: cellTokens.length > 0 ? 0.25 : 0.85,
                    zIndex: 1,
                  }}>{theme.arrow}</div>
                )}

                {cellTokens.map((token, tIdx) => {
                  const cfg = activePlayers.find(p => p.id === token.playerId)!
                  const isMovable = token.playerId === currentPlayer.id && movableTokenIds.includes(token.tokenId)

                  return (
                    <div
                      key={`${token.playerId}-${token.tokenId}`}
                      onClick={(e) => {
                        e.stopPropagation()
                        handleTokenClick(token.tokenId)
                      }}
                      className={isMovable ? 'btn-touch' : ''}
                      style={{
                        width: cellTokens.length > 1 ? '40%' : '75%',
                        height: cellTokens.length > 1 ? '40%' : '75%',
                        borderRadius: '50%',
                        background: cfg.color,
                        border: isMovable ? '2px solid #ffffff' : '1px solid rgba(255,255,255,0.4)',
                        boxShadow: isMovable
                          ? '0 0 10px #ffffff, 0 0 15px ' + cfg.color
                          : 'inset 0 0 5px rgba(0,0,0,0.5)',
                        cursor: isMovable ? 'pointer' : 'default',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        color: '#fff',
                        fontWeight: 'bold',
                        fontSize: cellTokens.length > 1 ? 8 : 10,
                        transform: isMovable ? 'scale(1.15)' : 'scale(1)',
                        animation: isMovable ? 'bounce 0.8s infinite alternate' : 'none',
                        zIndex: isMovable ? 10 : 2 + tIdx,
                        outline: 'none',
                        transition: 'all 0.2s',
                        WebkitTapHighlightColor: 'transparent',
                      }}
                    >
                      {token.tokenId + 1}
                    </div>
                  )
                })}
              </div>
            )
          })}
        </div>
      </div>

      {/* Bottom Corner Profiles Row: Red (Left), Blue (Right) */}
      <div style={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        width: '100%',
        maxWidth: 370,
        boxSizing: 'border-box'
      }}>
        {renderPlayerCard('red', false)}
        {renderPlayerCard('blue', true)}
      </div>

      {/* Action Buttons */}
      <div style={{ display: 'flex', gap: 10, width: '100%', maxWidth: 370, marginTop: 18 }}>
        <button onClick={() => resetGame(false)} className="btn-touch" style={{
          flex: 1, padding: '12px',
          background: 'transparent',
          border: '2px solid #ef4444',
          borderRadius: 12, color: '#ef4444',
          fontSize: 11, fontWeight: 900,
          letterSpacing: 2, textTransform: 'uppercase',
          cursor: 'pointer',
          outline: 'none',
          fontFamily: "'Courier New', monospace",
          WebkitTapHighlightColor: 'transparent',
        }}>
          ↺ RESET
        </button>
        <button onClick={() => router.back()} className="btn-touch" style={{
          flex: 1, padding: '12px',
          background: 'transparent',
          border: '1px solid #333',
          borderRadius: 12, color: '#555',
          fontSize: 11, fontWeight: 900,
          letterSpacing: 2, textTransform: 'uppercase',
          cursor: 'pointer',
          outline: 'none',
          fontFamily: "'Courier New', monospace",
          WebkitTapHighlightColor: 'transparent',
        }}>
          ← LOBBY
        </button>
      </div>

      {/* Winner Overlay Modal */}
      {winner && (
        <div style={{
          position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
          background: 'rgba(5, 5, 15, 0.9)',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          zIndex: 100, padding: 16
        }}>
          <div style={{
            background: '#0d0d20',
            border: '2px solid #eab308',
            borderRadius: 20,
            padding: '32px 24px',
            width: '100%',
            maxWidth: 340,
            textAlign: 'center',
            boxShadow: '0 0 24px rgba(234, 179, 8, 0.3)',
            boxSizing: 'border-box'
          }}>
            <div style={{ fontSize: 48, marginBottom: 12 }}>🏆</div>
            <h2 style={{ color: '#eab308', fontSize: 18, letterSpacing: 3, textTransform: 'uppercase', margin: '0 0 8px 0' }}>
              VICTORY!
            </h2>
            <p style={{ color: '#fff', fontSize: 18, fontWeight: 'bold', margin: '0 0 24px 0' }}>
              {winner.toUpperCase()} IS THE CHAMPION!
            </p>

            {rankings.length > 0 && (
              <div style={{ marginBottom: 24 }}>
                <h3 style={{ color: '#888', fontSize: 11, letterSpacing: 1, textTransform: 'uppercase', margin: '0 0 10px 0' }}>Final Rankings</h3>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 6, alignItems: 'center' }}>
                  {rankings.map((pId, idx) => {
                    const pName = activePlayers.find(ap => ap.id === pId)?.displayName || pId
                    const cfg = PLAYERS_CONFIG.find(p => p.id === pId)
                    return (
                      <div key={pId} style={{ display: 'flex', alignItems: 'center', gap: 8, color: '#fff', fontSize: 13, fontFamily: "'Courier New', monospace" }}>
                        <span style={{ color: '#eab308', fontWeight: 'bold' }}>#{idx + 1}</span>
                        <span style={{ color: cfg?.color || '#fff', fontWeight: 'bold' }}>{pName.toUpperCase()}</span>
                      </div>
                    )
                  })}
                </div>
              </div>
            )}

            <div style={{ display: 'flex', gap: 10 }}>
              <button onClick={() => resetGame(false)} className="btn-touch" style={{
                flex: 1, padding: '14px 12px',
                background: 'transparent',
                border: '2px solid #00ff88',
                borderRadius: 12, color: '#00ff88',
                fontSize: 11, fontWeight: 900,
                letterSpacing: 2, textTransform: 'uppercase',
                cursor: 'pointer',
                fontFamily: "'Courier New', monospace",
                outline: 'none',
                WebkitTapHighlightColor: 'transparent'
              }}>
                ↺ REMATCH
              </button>
              <button onClick={() => router.back()} className="btn-touch" style={{
                flex: 1, padding: '14px 12px',
                background: 'transparent',
                border: '1px solid #334155',
                borderRadius: 12, color: '#64748b',
                fontSize: 11, fontWeight: 900,
                letterSpacing: 2, textTransform: 'uppercase',
                cursor: 'pointer',
                fontFamily: "'Courier New', monospace",
                outline: 'none',
                WebkitTapHighlightColor: 'transparent'
              }}>
                ← LOBBY
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Inline styles for custom bouncing/tactile animations */}
      <style jsx global>{`
        @keyframes bounce {
          from {
            transform: scale(1.1) translateY(0);
          }
          to {
            transform: scale(1.1) translateY(-4px);
            box-shadow: 0 0 14px #fff;
          }
        }
        @keyframes pulse-dice {
          from {
            transform: scale(1);
          }
          to {
            transform: scale(1.06);
          }
        }
        .btn-touch {
          transition: transform 0.1s ease, filter 0.1s ease !important;
          -webkit-tap-highlight-color: transparent !important;
          outline: none !important;
        }
        .btn-touch:active {
          transform: scale(0.94) !important;
          filter: brightness(0.9) !important;
        }
        @keyframes pulse {
          0%, 100% { opacity: 0.3; }
          50% { opacity: 1; }
        }
        .dot-pulse {
          width: 24px;
          height: 24px;
          border-radius: 50%;
          background: #00ff88;
          display: inline-block;
          animation: pulse 1.5s infinite ease-in-out;
          box-shadow: 0 0 16px #00ff88;
        }
      `}</style>

      {isLoadingHistory && (
        <div style={{
          position: 'fixed', inset: 0, background: 'rgba(10, 10, 26, 0.95)',
          display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', zIndex: 1000
        }}>
          <div style={{ fontSize: 40, marginBottom: 12 }} className="dot-pulse" />
          <p style={{ color: '#fff', fontSize: 12, letterSpacing: 2, fontWeight: 'bold', textTransform: 'uppercase' }}>
            SYNCHRONIZING BOARD STATE...
          </p>
        </div>
      )}
    </main>
  )
}

export default function Ludo() {
  return (
    <Suspense fallback={<div style={{ color: '#fff', textAlign: 'center', marginTop: 100 }}>Loading Ludo...</div>}>
      <LudoContent />
    </Suspense>
  )
}

'use client'
import { useState, useEffect, useRef } from 'react'
import { useRouter } from 'next/navigation'
import {
  generateRoomCode,
  getSessionPlayerId,
  publishEvent,
  OnlineConnection
} from './lib/online'

const playerColors = [
  { border: '#00f0ff', emoji: '🎮' },
  { border: '#ff00ff', emoji: '🕹️' },
  { border: '#00ff88', emoji: '👾' },
  { border: '#ffaa00', emoji: '🏆' },
]

export default function Home() {
  const [gameMode, setGameMode] = useState<'local' | 'bot' | 'online'>('local')
  const [difficulty, setDifficulty] = useState<'easy' | 'medium' | 'hard'>('medium')
  const [firstTurn, setFirstTurn] = useState<'player' | 'bot' | 'random'>('player')
  const [playerCount, setPlayerCount] = useState(2)
  const [names, setNames] = useState(['', '', '', ''])

  // Online states
  const [onlineSubMode, setOnlineSubMode] = useState<'menu' | 'waiting_create' | 'waiting_join'>('menu')
  const [roomCode, setRoomCode] = useState('')
  const [joinCodeInput, setJoinCodeInput] = useState('')
  const [onlinePlayers, setOnlinePlayers] = useState<string[]>([])
  const [onlineStatus, setOnlineStatus] = useState<'connected' | 'connecting' | 'disconnected'>('disconnected')
  const connectionRef = useRef<any>(null)
  const processedIdsRef = useRef<Set<string>>(new Set())

  const router = useRouter()

  useEffect(() => {
    if (typeof window !== 'undefined') {
      const urlParams = new URLSearchParams(window.location.search)
      const joinParam = urlParams.get('join')
      if (joinParam) {
        const trimmedCode = joinParam.trim().toUpperCase()
        if (trimmedCode.length === 6) {
          setGameMode('online')
          setJoinCodeInput(trimmedCode)
        }
      }
    }
  }, [])

  useEffect(() => {
    return () => {
      if (connectionRef.current) {
        connectionRef.current.disconnect()
      }
    }
  }, [])

  function handleCreateRoom() {
    if (connectionRef.current) {
      connectionRef.current.disconnect()
    }
    const hostName = names[0].trim() || 'Player 1'
    const code = generateRoomCode()
    setRoomCode(code)
    setOnlinePlayers([hostName])
    setOnlineSubMode('waiting_create')

    const processedIds = new Set<string>()
    processedIdsRef.current = processedIds

    const conn = new OnlineConnection(
      code,
      (event) => {
        if (event.type === 'join') {
          setOnlinePlayers(prev => {
            const guestName = event.payload.name || `Player ${prev.length + 1}`
            const nextPlayers = [...prev, guestName]
            
            if (nextPlayers.length >= playerCount) {
              publishEvent(code, 'start_lobby', { players: nextPlayers })
              setTimeout(() => {
                conn.disconnect()
                const q = nextPlayers.map((n, i) => `p${i+1}=${encodeURIComponent(n)}`).join('&') + `&mode=online&room=${code}&role=host`
                router.push(`/games?${q}`)
              }, 500)
            } else {
              publishEvent(code, 'lobby_update', { players: nextPlayers })
            }
            return nextPlayers
          })
        }
      },
      (status) => setOnlineStatus(status),
      processedIds
    )

    connectionRef.current = conn
    conn.connect()
  }

  function handleJoinRoom() {
    if (connectionRef.current) {
      connectionRef.current.disconnect()
    }
    const guestName = names[0].trim() || 'Player 2'
    const code = joinCodeInput.trim().toUpperCase()
    if (code.length !== 6) {
      alert('Please enter a valid 6-character room code.')
      return
    }
    setRoomCode(code)
    setOnlinePlayers([guestName])
    setOnlineSubMode('waiting_join')

    const processedIds = new Set<string>()
    processedIdsRef.current = processedIds

    let hasJoined = false

    const conn = new OnlineConnection(
      code,
      (event) => {
        if (event.type === 'lobby_update') {
          setOnlinePlayers(event.payload.players)
        } else if (event.type === 'start_lobby') {
          const nextPlayers = event.payload.players
          const myIdx = nextPlayers.indexOf(guestName)
          const role = myIdx >= 0 ? `guest${myIdx}` : 'guest1'
          
          conn.disconnect()
          const q = nextPlayers.map((n: string, i: number) => `p${i+1}=${encodeURIComponent(n)}`).join('&') + `&mode=online&room=${code}&role=${role}`
          router.push(`/games?${q}`)
        }
      },
      async (status) => {
        setOnlineStatus(status)
        if (status === 'connected' && !hasJoined) {
          hasJoined = true
          await publishEvent(code, 'join', { name: guestName })
        }
      },
      processedIds
    )

    connectionRef.current = conn
    conn.connect()
  }

  function updateName(i: number, val: string) {
    const u = [...names]; u[i] = val; setNames(u)
  }

  function startGame() {
    console.log("startGame called, gameMode:", gameMode, "playerCount:", playerCount)
    try {
      if (gameMode === 'local') {
        const active = names.slice(0, playerCount).map((n, i) => {
          const trimmed = typeof n === 'string' ? n.trim() : ''
          return trimmed || `Player ${i+1}`
        })
        const q = active.map((n, i) => `p${i+1}=${encodeURIComponent(n)}`).join('&')
        router.push(`/games?${q}`)
      } else {
        const p1Name = names[0].trim() || 'Player 1'
        const isBotFirst = firstTurn === 'bot' || (firstTurn === 'random' && Math.random() < 0.5)
        const p1NameParam = isBotFirst ? 'Bot' : p1Name
        const p2NameParam = isBotFirst ? p1Name : 'Bot'
        const q = `p1=${encodeURIComponent(p1NameParam)}&p2=${encodeURIComponent(p2NameParam)}&mode=bot&difficulty=${difficulty}&first=${firstTurn}`
        router.push(`/games?${q}`)
      }
    } catch (err) {
      console.error("Error in startGame:", err)
    }
  }

  return (
    <main style={{
      minHeight: '100dvh',
      background: '#0a0a1a',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '20px 16px',
      fontFamily: "'Courier New', monospace",
      boxSizing: 'border-box',
      overflowX: 'hidden',
    }}>

      {/* Background glows */}
      <div style={{ position:'fixed', top:-100, left:-100, width:300, height:300, borderRadius:'50%', background:'#00f0ff', opacity:0.05, filter:'blur(80px)', pointerEvents:'none' }}/>
      <div style={{ position:'fixed', bottom:-100, right:-100, width:300, height:300, borderRadius:'50%', background:'#ff00ff', opacity:0.05, filter:'blur(80px)', pointerEvents:'none' }}/>

      {/* Card */}
      <div style={{
        width: '100%',
        maxWidth: 400,
        background: '#0d0d20',
        border: '2px solid #00f0ff',
        borderRadius: 20,
        padding: '28px 20px',
        boxShadow: '0 0 30px #00f0ff22',
        boxSizing: 'border-box',
      }}>

        {/* Header */}
        <div style={{ textAlign:'center', marginBottom:24 }}>
          <div style={{ fontSize:48, marginBottom:8 }}>🎮</div>
          <h1 style={{
            fontSize: 26, fontWeight:900, color:'#fff',
            letterSpacing:5, textTransform:'uppercase',
            textShadow:'0 0 20px #00f0ff',
            margin:0,
          }}>POCKETARCADE X</h1>
          <div style={{ height:1, background:'linear-gradient(to right, transparent, #00f0ff, transparent)', marginTop:10 }}/>
        </div>
        {/* Game Mode Selector */}
        <div style={{ display:'flex', border:'1px solid #333', borderRadius:14, padding:4, gap:4, marginBottom:20 }}>
          <button type="button" onClick={() => { setGameMode('local'); setOnlineSubMode('menu'); }} style={{
            flex:1, padding:'10px 0', borderRadius:10, border:'none',
            background: gameMode === 'local' ? '#00f0ff22' : 'transparent',
            color: gameMode === 'local' ? '#00f0ff' : '#666',
            fontWeight: 900, fontSize:10, cursor:'pointer', letterSpacing:1,
            transition:'all 0.2s', outline:'none',
            fontFamily:"'Courier New', monospace",
          }}>
            👥 LOCAL
          </button>
          <button type="button" onClick={() => { setGameMode('bot'); setOnlineSubMode('menu'); }} style={{
            flex:1, padding:'10px 0', borderRadius:10, border:'none',
            background: gameMode === 'bot' ? '#ff00ff22' : 'transparent',
            color: gameMode === 'bot' ? '#ff00ff' : '#666',
            fontWeight: 900, fontSize:10, cursor:'pointer', letterSpacing:1,
            transition:'all 0.2s', outline:'none',
            fontFamily:"'Courier New', monospace",
          }}>
            🤖 BOT
          </button>
          <button type="button" onClick={() => setGameMode('online')} style={{
            flex:1, padding:'10px 0', borderRadius:10, border:'none',
            background: gameMode === 'online' ? '#00ff8822' : 'transparent',
            color: gameMode === 'online' ? '#00ff88' : '#666',
            fontWeight: 900, fontSize:10, cursor:'pointer', letterSpacing:1,
            transition:'all 0.2s', outline:'none',
            fontFamily:"'Courier New', monospace",
          }}>
            🌐 ONLINE
          </button>
        </div>

        {gameMode === 'local' && (
          <>
            {/* Player count */}
            <p style={{ color:'#666', fontSize:10, letterSpacing:4, textTransform:'uppercase', textAlign:'center', marginBottom:12 }}>
              NUMBER OF PLAYERS
            </p>
            <div style={{ display:'flex', gap:10, justifyContent:'center', marginBottom:24 }}>
              {[1,2,3,4].map(n => (
                <button key={n} type="button" onClick={()=>setPlayerCount(n)} style={{
                  width: 64, height: 64,
                  borderRadius: 14,
                  border: `2px solid ${playerCount===n ? '#00f0ff' : '#333'}`,
                  background: playerCount===n ? '#00f0ff22' : 'transparent',
                  color: playerCount===n ? '#00f0ff' : '#555',
                  fontSize: 22, fontWeight:900,
                  cursor:'pointer',
                  boxShadow: playerCount===n ? '0 0 16px #00f0ff44' : 'none',
                  transition:'all 0.2s',
                  WebkitTapHighlightColor:'transparent',
                  fontFamily:"'Courier New', monospace",
                }}>{n}</button>
              ))}
            </div>

            {/* Divider */}
            <div style={{ borderTop:'1px solid #1a1a3a', marginBottom:20 }}/>

            {/* Name inputs */}
            <div style={{ display:'flex', flexDirection:'column', gap:12, marginBottom:20 }}>
              {Array.from({ length: playerCount }).map((_,i) => (
                <div key={i} style={{ display:'flex', alignItems:'center', gap:10 }}>
                  <div style={{
                    width:40, height:40, borderRadius:10, flexShrink:0,
                    border:`2px solid ${playerColors[i].border}`,
                    background:`${playerColors[i].border}11`,
                    display:'flex', alignItems:'center', justifyContent:'center',
                    fontSize:18,
                  }}>
                    {playerColors[i].emoji}
                  </div>
                  <input
                    type="text"
                    placeholder={i === 0 ? "🎮 Player 1" : `👤 Player ${i+1}`}
                    value={names[i]}
                    onChange={e=>updateName(i,e.target.value)}
                    style={{
                      flex:1,
                      background:'#111',
                      border:`1px solid #333`,
                      borderRadius:10,
                      padding:'13px 14px',
                      color:'#fff',
                      fontSize:14,
                      letterSpacing:1,
                      outline:'none',
                      fontFamily:"'Courier New', monospace",
                      WebkitAppearance:'none',
                      boxSizing:'border-box',
                    }}
                    onFocus={e=>e.target.style.borderColor=playerColors[i].border}
                    onBlur={e=>e.target.style.borderColor='#333'}
                  />
                </div>
              ))}
            </div>
          </>
        )}

        {gameMode === 'bot' && (
          <>
            {/* Player name input (only 1) */}
            <div style={{ display:'flex', flexDirection:'column', gap:12, marginBottom:20 }}>
              <div style={{ display:'flex', alignItems:'center', gap:10 }}>
                <div style={{
                  width:40, height:40, borderRadius:10, flexShrink:0,
                  border:`2px solid ${playerColors[0].border}`,
                  background:`${playerColors[0].border}11`,
                  display:'flex', alignItems:'center', justifyContent:'center',
                  fontSize:18,
                }}>
                  {playerColors[0].emoji}
                </div>
                <input
                  type="text"
                  placeholder="🎮 Player 1"
                  value={names[0]}
                  onChange={e=>updateName(0,e.target.value)}
                  style={{
                    flex:1,
                    background:'#111',
                    border:`1px solid #333`,
                    borderRadius:10,
                    padding:'13px 14px',
                    color:'#fff',
                    fontSize:14,
                    letterSpacing:1,
                    outline:'none',
                    fontFamily:"'Courier New', monospace",
                    WebkitAppearance:'none',
                    boxSizing:'border-box',
                  }}
                  onFocus={e=>e.target.style.borderColor=playerColors[0].border}
                  onBlur={e=>e.target.style.borderColor='#333'}
                />
              </div>
            </div>

            {/* Bot Difficulty */}
            <p style={{ color:'#666', fontSize:10, letterSpacing:4, textTransform:'uppercase', textAlign:'center', marginBottom:12 }}>
              BOT DIFFICULTY
            </p>
            <div style={{ display:'flex', gap:8, justifyContent:'center', marginBottom:20 }}>
              {(['easy', 'medium', 'hard'] as const).map(d => {
                const diffColors = {
                  easy: { border: '#22c55e', bg: '#22c55e22', text: '#22c55e', label: '🟢 EASY' },
                  medium: { border: '#eab308', bg: '#eab30822', text: '#eab308', label: '🟡 MEDIUM' },
                  hard: { border: '#ef4444', bg: '#ef444422', text: '#ef4444', label: '🔴 HARD' }
                }
                const active = difficulty === d
                return (
                  <button key={d} type="button" onClick={()=>setDifficulty(d)} style={{
                    flex: 1, height: 44,
                    borderRadius: 12,
                    border: `2px solid ${active ? diffColors[d].border : '#333'}`,
                    background: active ? diffColors[d].bg : 'transparent',
                    color: active ? diffColors[d].text : '#555',
                    fontSize: 10, fontWeight:900, letterSpacing: 2,
                    cursor:'pointer',
                    transition:'all 0.2s',
                    WebkitTapHighlightColor:'transparent',
                    fontFamily:"'Courier New', monospace",
                  }}>{diffColors[d].label}</button>
                )
              })}
            </div>

            {/* Who Goes First? */}
            <p style={{ color:'#666', fontSize:10, letterSpacing:4, textTransform:'uppercase', textAlign:'center', marginBottom:12 }}>
              WHO GOES FIRST?
            </p>
            <div style={{ display:'flex', gap:8, justifyContent:'center', marginBottom:24 }}>
              {(['player', 'bot', 'random'] as const).map(f => {
                const firstLabels = {
                  player: '👤 PLAYER',
                  bot: '🤖 BOT',
                  random: '🎲 RANDOM'
                }
                const active = firstTurn === f
                const activeColor = f === 'player' ? '#00f0ff' : f === 'bot' ? '#ff00ff' : '#00ff88'
                return (
                  <button key={f} type="button" onClick={()=>setFirstTurn(f)} style={{
                    flex: 1, height: 44,
                    borderRadius: 12,
                    border: `2px solid ${active ? activeColor : '#333'}`,
                    background: active ? `${activeColor}22` : 'transparent',
                    color: active ? activeColor : '#555',
                    fontSize: 10, fontWeight:900, letterSpacing: 1,
                    cursor:'pointer',
                    transition:'all 0.2s',
                    WebkitTapHighlightColor:'transparent',
